import { computed, onBeforeUnmount, ref, useId } from "vue";
import { animate } from "motion-v";
import { useControllable } from "../../shared";
import { useReducedMotion } from "../../../lib/composables";
import { EASE_OUT } from "../../../lib/ease";
import { amountInputSize, buildQuote, payoutTickerSize } from "./utils";
import type {
  PredictionMarketOrderValue as Order,
  PredictionMarketOutcome as Outcome,
  PredictionMarketQuote as Quote,
} from "./types";
export function useMarketOrder(
  props: {
    modelValue?: Order;
    defaultValue?: Partial<Order>;
    outcomes: Outcome[];
    positions: Record<string, number>;
    balance: number;
    minTrade: number;
    authenticated: boolean;
  },
  events: {
    change: (value: Order) => void;
    trade: (order: Order, quote: Quote) => void;
    signIn: () => void;
  },
) {
  const order = useControllable(
    () => props.modelValue,
    {
      mode: "buy" as const,
      outcomeId: props.outcomes[0]?.id ?? "",
      amount: "",
      ...props.defaultValue,
    },
    events.change,
  );
  const selected = computed(
    () =>
      props.outcomes.find((outcome) => outcome.id === order.value.outcomeId) ??
      props.outcomes[0],
  );
  const position = computed(
    () => props.positions[selected.value?.id ?? ""] ?? 0,
  );
  const quote = computed(() =>
    buildQuote({
      order: order.value,
      outcome: selected.value ?? { id: "", label: "", price: 0 },
      balance: props.balance,
      position: position.value,
      minTrade: props.minTrade,
    }),
  );
  const status = ref<"idle" | "placing" | "filled">("idle"),
    reduce = useReducedMotion(),
    id = useId(),
    amount = ref<HTMLElement>();
  const actionState = computed(() =>
    status.value === "placing"
      ? "loading"
      : status.value === "filled"
        ? "success"
        : quote.value.valid
          ? "idle"
          : "error",
  );
  const inputSize = computed(() => amountInputSize(order.value.amount)),
    payoutSize = computed(() => payoutTickerSize(quote.value.payout));
  let timer: ReturnType<typeof setTimeout> | undefined,
    shake: ReturnType<typeof animate> | undefined;
  function patch(value: Partial<Order>) {
    clearTimeout(timer);
    status.value = "idle";
    order.value = { ...order.value, ...value };
  }
  function max() {
    patch({
      amount:
        order.value.mode === "buy"
          ? String(Math.floor(props.balance))
          : position.value.toFixed(position.value % 1 === 0 ? 0 : 2),
    });
  }
  function submit() {
    if (!props.authenticated) {
      events.signIn();
      return;
    }
    if (!quote.value.valid) {
      if (amount.value && !reduce.value) {
        shake?.stop();
        shake = animate(
          amount.value,
          { x: [0, -5, 5, -3, 3, -1, 0] },
          { duration: 0.38, ease: EASE_OUT },
        );
      }
      return;
    }
    if (status.value === "placing") return;
    status.value = "placing";
    const payload = { ...order.value },
      valuation = { ...quote.value };
    timer = setTimeout(() => {
      status.value = "filled";
      events.trade(payload, valuation);
    }, 650);
  }
  onBeforeUnmount(() => {
    clearTimeout(timer);
    shake?.stop();
  });
  return {
    order,
    selected,
    quote,
    reduce,
    id,
    amount,
    status,
    actionState,
    inputSize,
    payoutSize,
    patch,
    max,
    submit,
  };
}

import type {
  PredictionMarketOrderValue,
  PredictionMarketOutcome,
  PredictionMarketQuote,
} from "./types";
export function sanitizeAmount(value: string) {
  let whole = "",
    fraction = "",
    decimal = false;
  for (const char of value) {
    if (char === "." && !decimal) {
      decimal = true;
      continue;
    }
    if (char < "0" || char > "9") continue;
    if (!decimal) whole += char;
    else if (fraction.length < 2) fraction += char;
  }
  return whole + (decimal ? "." + fraction : "");
}
export const parseAmount = (value: string) => Number(value) || 0;
export const formatCurrency = (value: number, maximumFractionDigits = 2) =>
  new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits,
  }).format(value);
export const formatCompactCurrency = (value: number) =>
  formatCurrency(value, value >= 100 || value % 1 === 0 ? 0 : 2);
export function formatCents(value: number) {
  const cents = value * 100;
  return cents.toFixed(Number.isInteger(cents) ? 0 : 1) + "¢";
}
export function buildQuote({
  order,
  outcome,
  balance,
  position,
  minTrade,
}: {
  order: PredictionMarketOrderValue;
  outcome: PredictionMarketOutcome;
  balance: number;
  position: number;
  minTrade: number;
}): PredictionMarketQuote {
  const amount = parseAmount(order.amount),
    price = Math.min(0.99, Math.max(0.01, outcome.price));
  const shares = order.mode === "buy" ? amount / price : amount,
    payout = order.mode === "buy" ? shares : amount * price;
  if (amount <= 0)
    return {
      valid: false,
      amount,
      price,
      shares: 0,
      payout: 0,
      error: "Enter an amount",
    };
  const error =
    order.mode === "buy"
      ? amount < minTrade
        ? `Minimum ${formatCompactCurrency(minTrade)}`
        : amount > balance
          ? "Insufficient balance"
          : undefined
      : amount > position
        ? "Not enough shares"
        : undefined;
  return {
    valid: error === undefined,
    amount,
    price,
    shares,
    payout,
    ...(error ? { error } : {}),
  };
}
export function keyedAmountChars(value: string) {
  const occurrences: Record<string, number> = Object.create(null);
  return Array.from(value, (char) => {
    const occurrence = occurrences[char] ?? 0;
    occurrences[char] = occurrence + 1;
    return { id: `${char}-${occurrence}`, char };
  });
}
export function amountInputSize(value: string) {
  const count = Array.from(value).filter(
    (char) => char >= "0" && char <= "9",
  ).length;
  return count >= 10
    ? "text-3xl sm:text-4xl"
    : count >= 8
      ? "text-4xl sm:text-5xl"
      : count >= 6
        ? "text-[44px] sm:text-[56px]"
        : "text-5xl sm:text-6xl";
}
export function payoutTickerSize(value: number) {
  const count = formatCurrency(value).length;
  return count >= 16
    ? "text-xl sm:text-2xl"
    : count >= 13
      ? "text-2xl"
      : count >= 10
        ? "text-3xl"
        : "text-4xl";
}
export const probability = (value: number) =>
  Number.isFinite(value) ? Math.min(1, Math.max(0, value)) : 0;
export function historyPoints(values: number[]) {
  const samples = values.filter(Number.isFinite);
  if (samples.length < 2) return null;
  let low = Infinity,
    high = -Infinity;
  for (const sample of samples) {
    low = Math.min(low, sample);
    high = Math.max(high, sample);
  }
  return samples
    .map(
      (value, index) =>
        `${2 + (44 * index) / (samples.length - 1)},${18 - 14 * (high === low ? 0.5 : (value - low) / (high - low))}`,
    )
    .join(" ");
}

import { useBlockDismiss } from "./dismiss";
import { resolveElement, useOverlay } from "../lib/composables";
import {
  computed,
  defineComponent,
  h,
  isVNode,
  onMounted,
  onUnmounted,
  ref,
  type Component,
  type Ref,
  type VNodeChild,
} from "vue";

export type Content = VNodeChild | Component;
export const RenderNode = defineComponent({
  props: ["node"],
  setup(props) {
    return () => {
      const node = props.node;
      if (isVNode(node) || node === null || node === undefined) return node;
      if (typeof node === "function" || typeof node === "object")
        return h(node as Component);
      return node;
    };
  },
});

export function useControllable<T>(
  get: () => T | undefined,
  initial: T,
  emit: (value: T) => void,
) {
  const saved = ref(initial) as Ref<T>;
  return computed<T>({
    get() {
      const value = get();
      return value === undefined ? saved.value : value;
    },
    set(value) {
      if (get() === undefined) saved.value = value;
      emit(value);
    },
  });
}

export function useOutside(
  root: Ref<HTMLElement | undefined>,
  close: () => void,
  open: Ref<boolean>,
) {
  useBlockDismiss(open, root, close);
}

export function useReduced() {
  const reduced = ref(false);
  let detach: (() => void) | undefined;
  onMounted(() => {
    if (typeof matchMedia !== "function") return;
    const query = matchMedia("(prefers-reduced-motion: reduce)");
    const read = () => {
      reduced.value = query.matches;
    };
    read();
    query.addEventListener("change", read);
    detach = () => query.removeEventListener("change", read);
  });
  onUnmounted(() => detach?.());
  return reduced;
}

export function rove(
  event: KeyboardEvent,
  root: HTMLElement,
  selector = "button:not(:disabled)",
) {
  const items = [...root.querySelectorAll<HTMLElement>(selector)];
  if (!items.length) return;
  const current = items.indexOf(
    root.ownerDocument.activeElement as HTMLElement,
  );
  let destination: number;
  switch (event.key) {
    case "ArrowRight":
    case "ArrowDown":
      destination = (current + 1) % items.length;
      break;
    case "ArrowLeft":
    case "ArrowUp":
      destination = (current - 1 + items.length) % items.length;
      break;
    case "Home":
      destination = 0;
      break;
    case "End":
      destination = items.length - 1;
      break;
    default:
      return;
  }
  event.preventDefault();
  items[destination]?.focus();
}

export function useDialog(
  open: Ref<boolean>,
  root: Ref<HTMLElement | undefined>,
  initial?: () => HTMLElement | undefined,
) {
  const element = computed(() => resolveElement<HTMLElement>(root.value));
  useOverlay(
    open,
    element,
    () => {
      open.value = false;
    },
    initial,
  );
}

import { computed, getCurrentInstance, nextTick, onBeforeUnmount, onMounted, ref, watch, type Ref } from "vue";
import { layerManager, type Layer } from "./layers";

export function useControllable<T>(props: Record<string, any>, key: string, emit: (...args: any[]) => void, fallback: T) {
  const local = ref<T>(fallback) as Ref<T>;
  const read = () => props[key] as T | undefined;
  return computed<T>({
    get() { const supplied = read(); return supplied === undefined ? local.value : supplied; },
    set(value) { if (read() === undefined) local.value = value; emit(`update:${key}`, value); },
  });
}

export function useMediaQuery(query: string) {
  const matches = ref(false);
  let disconnect: (() => void) | undefined;
  onMounted(() => {
    if (typeof window.matchMedia !== "function") return;
    const media = window.matchMedia(query);
    const update = () => { matches.value = media.matches; };
    update();
    media.addEventListener?.("change", update);
    disconnect = () => media.removeEventListener?.("change", update);
  });
  onBeforeUnmount(() => disconnect?.());
  return matches;
}
export function useReducedMotion() { return useMediaQuery("(prefers-reduced-motion: reduce)"); }

const lockedProperties = ["overflow", "position", "top", "left", "right", "width"] as const;
let scrollOwners = 0;
let unlockPage: (() => void) | undefined;
function acquirePage() {
  if (scrollOwners++ === 0) {
    const body = document.body.style;
    const saved = lockedProperties.map(name => ({ name, value: body.getPropertyValue(name), priority: body.getPropertyPriority(name) }));
    const x = window.scrollX, y = window.scrollY;
    body.setProperty("overflow", "hidden");
    body.setProperty("position", "fixed");
    body.setProperty("left", `${-x}px`);
    body.setProperty("top", `${-y}px`);
    body.setProperty("right", "0px");
    body.setProperty("width", "100%");
    unlockPage = () => {
      for (const entry of saved) {
        if (entry.value) body.setProperty(entry.name, entry.value, entry.priority);
        else body.removeProperty(entry.name);
      }
      const root = document.documentElement.style;
      const behavior = root.getPropertyValue("scroll-behavior");
      const priority = root.getPropertyPriority("scroll-behavior");
      root.setProperty("scroll-behavior", "auto");
      window.scrollTo(x, y);
      if (behavior) root.setProperty("scroll-behavior", behavior, priority);
      else root.removeProperty("scroll-behavior");
    };
  }
  let released = false;
  return () => {
    if (released) return;
    released = true;
    if (--scrollOwners === 0) { unlockPage?.(); unlockPage = undefined; }
  };
}
export function useScrollLock(locked: Ref<boolean>) {
  let mounted = false;
  let release: (() => void) | undefined;
  const update = (value: boolean) => {
    if (!mounted) return;
    if (value && !release) release = acquirePage();
    if (!value && release) { release(); release = undefined; }
  };
  onMounted(() => { mounted = true; update(locked.value); });
  watch(locked, update);
  onBeforeUnmount(() => { release?.(); release = undefined; mounted = false; });
}

export function resolveElement<T extends Element = HTMLElement>(value: unknown): T | null {
  if (!value) return null;
  const unwrapped = (value as { $el?: unknown }).$el ?? value;
  return typeof (unwrapped as Element).nodeType === "number" && (unwrapped as Element).nodeType === 1 ? unwrapped as T : null;
}
const focusable = 'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
function createLayer(modal: boolean, panel?: { readonly value: unknown }): Layer {
  return { key: Symbol("orvui-layer"), modal, owner: getCurrentInstance(), surface: () => resolveElement(panel?.value), returnTo: null };
}
export function useOverlay(open: Ref<boolean>, panel: Ref<HTMLElement | null>, close: () => void, initialFocus?: () => HTMLElement | undefined) {
  const layer = createLayer(true, panel);
  let mounted = false;
  let revision = 0;
  const sync = async (value: boolean) => {
    const current = ++revision;
    if (!mounted) return;
    if (!value) { layerManager.detach(layer, true); return; }
    if (!layerManager.attach(layer)) return;
    await nextTick();
    if (!mounted || current !== revision || !open.value || !layerManager.top(layer)) return;
    (initialFocus?.() ?? layer.surface()?.querySelector<HTMLElement>(focusable) ?? layer.surface())?.focus({ preventScroll: true });
  };
  const onKey = (event: KeyboardEvent) => {
    if (event.defaultPrevented || !open.value) return;
    if (event.key === "Escape" && layerManager.top(layer)) {
      event.preventDefault(); event.stopPropagation(); close(); return;
    }
    if (event.key !== "Tab" || !layerManager.modal(layer)) return;
    const candidates = new Set<HTMLElement>();
    for (const surface of layerManager.scopes(layer)) {
      for (const node of surface.querySelectorAll<HTMLElement>(focusable)) {
        if (node.getClientRects().length > 0 && !node.closest("[inert]")) candidates.add(node);
      }
    }
    event.preventDefault();
    const nodes = [...candidates];
    if (!nodes.length) { layer.surface()?.focus(); return; }
