    hull.push(current);
    let next = points.find((point) => point !== current)!;
    for (const point of points) {
      if (point === current) continue;
      const direction = cross(current, next, point);
      if (
        direction < 0 ||
        (direction === 0 && squared(current, point) > squared(current, next))
      )
        next = point;
